// Construir el array de mensajes para Ollama (guardrails Nivel 0).
// Defensa en profundidad: el backend ya valida; aquí se repite el filtro
// porque el webhook también podría recibir llamadas directas.
const MAX_HIST = 20;
const MAX_CONTENT = 2000;
const MAX_MENSAJE = 9000;
const MAX_SISTEMA = 4000;
const MAX_NUM_PREDICT = 1024;
const NUM_CTX = 8192;

const rolesValidos = new Set(['user', 'assistant']);
const recortar = (v, max) => (typeof v === 'string' ? v.slice(0, max) : '');

const sistema = recortar($input.item.json.sistema, MAX_SISTEMA) ||
  'Eres un asistente técnico de soporte IT. Responde en español, de forma clara y concisa.';

const historial = Array.isArray($input.item.json.historial)
  ? $input.item.json.historial
      .filter(m => m && rolesValidos.has(m.role) && typeof m.content === 'string')
      .slice(-MAX_HIST)
      .map(m => ({ role: m.role, content: recortar(m.content, MAX_CONTENT) }))
  : [];

const mensajes = [
  { role: 'system', content: sistema },
  ...historial,
  { role: 'user', content: recortar($input.item.json.mensaje, MAX_MENSAJE) }
];

const numPredict = parseInt($input.item.json.num_predict, 10);
const temperatura = parseFloat($input.item.json.temperatura);
const topP = parseFloat($input.item.json.top_p);

return [{
  json: {
    model: $input.item.json.modelo || 'llama3.2:3b',
    messages: mensajes,
    stream: false,
    options: {
      temperature: Number.isFinite(temperatura) ? temperatura : 0.8,
      top_p: Number.isFinite(topP) ? topP : 0.9,
      num_predict: Number.isFinite(numPredict) ? Math.min(Math.max(numPredict, 1), MAX_NUM_PREDICT) : 512,
      num_ctx: NUM_CTX
    }
  }
}];

// Procesar respuesta de Ollama
const respuesta = $input.item.json;

let textoRespuesta = '';
let tokensInfo = {};

if (respuesta.message && respuesta.message.content) {
  textoRespuesta = respuesta.message.content;
}

if (respuesta.eval_count) {
  tokensInfo = {
    tokens_generados: respuesta.eval_count,
    tokens_segundo: respuesta.eval_count / (respuesta.eval_duration / 1e9 || 1),
    tiempo_total_ms: Math.round((respuesta.total_duration || 0) / 1e6)
  };
}

return [{
  json: {
    respuesta: textoRespuesta,
    modelo: respuesta.model,
    tokens: tokensInfo,
    timestamp: new Date().toISOString(),
    status: 'success'
  }
}];
